UPDATE user_case SET ai_summary='{"title": "45岁男性胸闷咨询", "description": "患者45岁，男性，主诉胸闷，经常吸烟，AI建议注意休息，监测血压心率，避免紧张焦虑，戒烟，就医咨询。需排除心脏问题、肺部疾病、肌肉骨骼问题或心理因素等可能原因。", "basic_info": "姓名：未提供；年龄：45岁；性别：男；问诊科室：心内科；特殊情况备注：经常吸烟", "clinical": "主诉胸闷，无明确诱因，持续时间不定，活动后可能加重，伴随症状不详。", "diagnosis": "初步诊断：胸闷原因待查，需排除心脏问题、肺部疾病、肌肉骨骼问题或心理因素等。", "treatment": "1. 休息与观察，注意血压和心率；2. 避免紧张和焦虑，尝试深呼吸、放松技巧或冥想；3. 戒烟，减少吸烟量或寻求戒烟帮助；4. 就医咨询，根据医生建议进行心电图（ECG）、胸部X光、血液检查等。", "follow_up": "1. 注意胸闷症状的变化，若持续存在或加重，及时就医；2. 定期监测血压和心率；3. 遵循医生的建议进行治疗。", "tags": "胸闷,吸烟,休息,血压,心率", "category_id": 1}', title='45岁男性胸闷咨询', category_id=1, update_time=NOW() WHERE id=9;
